const NV: Record<string, any> = {"06.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Региональная неделя (02–08.11). На vote.duma.gov.ru за 06.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=06.11.2026&to=06.11.2026"], ["Председатель ГД", "В. Володин принял участие в оперативном совещании Президента России с членами Совета Безопасности.", "http://duma.gov.ru/news/64418/"], ["Председатель ГД", "В. Володин: вступил в силу закон от 04.08.2026 № 294-ФЗ — перечень статей КоАП, по которым кроме штрафа предусмотрено выдворение мигрантов, увеличился более чем в 2 раза.", "http://duma.gov.ru/news/64411/"], ["Комитет по уголовному и административному законодательству", "Рекомендовал отклонить законопроект о штрафах за опасное вождение: штраф 5 тыс. руб., за повторное нарушение — лишение прав на срок от 1 до 3 месяцев.", "http://duma.gov.ru/news/64417/"], ["Комитет по аграрным вопросам", "Определил приоритеты на осеннюю сессию: до конца 2026 года — принятие не менее девяти федеральных законов.", "http://duma.gov.ru/news/64413/"], ["ПА ОДКБ", "Заседание Постоянной комиссии ПА ОДКБ по вопросам обороны и безопасности: обсуждались проекты модельных законов.", "http://duma.gov.ru/news/64412/"]], "g": [["Совет Безопасности", "М. Мишустин принял участие в оперативном совещании у Президента с членами Совета Безопасности.", "http://www.kremlin.ru/events/president/news/81192"], ["Топливный рынок", "А. Новак провел совещание по ситуации на рынке топлива (Минэнерго, ФАС, Минтранс, Госдума, Совет Федерации, компании, главы регионов). ФАС: возбуждено 76 дел, выдано 109 предупреждений, 75 из них исполнено.", "http://government.ru/news/60389/"], ["Туризм", "Д. Чернышенко провел в Кировске (Мурманская область) заседание Правительственной комиссии по развитию туризма: около 71 млн поездок по России за девять месяцев 2026 года.", "http://government.ru/news/60390/"]]}, "07.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Суббота. На vote.duma.gov.ru за 07.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=07.11.2026&to=07.11.2026"], ["Председатель ГД", "В. Володин: свыше 60% регионов ввели ограничения на продажу вейпов, 17 регионов — запрет; депутаты держат тему на контроле.", "http://duma.gov.ru/news/64416/"]], "g": [["Премии имени Е. К. Федорова", "Распоряжение от 5 ноября 2026 года № 3216-р: в 2027 году присуждаются три премии в области гидрометеорологии, лауреаты получат по 1 млн руб., почетные знаки и дипломы.", "http://government.ru/news/60385/"], ["Центры занятости", "Распоряжение от 5 ноября 2026 года № 3221-р: из резервного фонда — около 120 млн руб. на модернизацию региональных центров занятости (федеральный проект «Управление рынком труда», нацпроект «Кадры»).", "http://government.ru/news/60386/"]]}, "08.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Воскресенье. На vote.duma.gov.ru за 08.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=08.11.2026&to=08.11.2026"]], "g": [["ТОР «Хабаровск»", "Постановление от 5 ноября 2026 года № 1459: границы ТОР расширены для нового инвестиционного проекта (участок в Тугуро-Чумиканском районе).", "http://government.ru/news/60387/"], ["Озимые", "Распоряжение № 3238-р: свыше 13 млрд руб. регионам в 2026 году на компенсацию части затрат аграриев на агротехнологические работы под урожай 2027 года.", "http://government.ru/news/60388/"]]}, "09.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "На vote.duma.gov.ru за 09.11.2026 голосований не найдено; пленарные заседания — с 10.11.", "http://vote.duma.gov.ru/?from=09.11.2026&to=09.11.2026"], ["Совет ГД", "По итогам Совета ГД: на 11.11 в первом чтении — законопроект о зачете в стаж муниципальной службы военной службы по контракту и службы в войсках национальной гвардии; на неделе — инициативы о поддержке участников СВО и сотрудников правоохранительных органов.", "http://duma.gov.ru/news/64428/"], ["Совет ГД", "Совет ГД определил 11 ноября датой рассмотрения во втором чтении законопроекта об исключении сведений об ингредиентах табачной и никотинсодержащей продукции из коммерческой тайны.", "http://duma.gov.ru/news/64430/"], ["Председатель ГД", "В. Володин провел совещание с руководителями фракций с участием Председателя ЦБ Э. Набиуллиной; 12 ноября ГД планирует обсудить доклад главы ЦБ об Основных направлениях ДКП.", "http://duma.gov.ru/news/64422/"], ["Комитеты", "Совместное заседание комитетов по финансовому рынку, по бюджету и налогам и по экономической политике с Э. Набиуллиной: Основные направления ДКП на 2027–2029 годы.", "http://duma.gov.ru/news/64426/"], ["Комитет по конституционному законодательству и судоустройству", "Рассмотрен пакет законопроектов Верховного Суда (№ 54-9, 55-9, 59-9, 64-9): дополнительные выплаты судьям и работникам аппаратов судов, передача административных функций.", "http://duma.gov.ru/news/64425/"], ["Председатель ГД", "Встреча В. Володина с губернатором Херсонской области В. Сальдо.", "http://duma.gov.ru/news/64424/"]], "g": [["Оперативное совещание", "Совещание с вице-премьерами: списание части задолженности регионов по бюджетным кредитам, поддержка малого агробизнеса, очистные сооружения.", "http://government.ru/news/60394/"], ["Бюджетные кредиты", "Распоряжение от 31 октября 2026 года № 3165-р: семи регионам списаны две трети задолженности по бюджетным кредитам, почти 12,5 млрд руб.", "http://government.ru/news/60395/"], ["Малый агробизнес", "Постановление от 30 октября 2026 года № 1433: расширены параметры поддержки приоритетных направлений малого агробизнеса в госпрограмме развития сельского хозяйства.", "http://government.ru/news/60396/"], ["Очистные сооружения", "Распоряжение от 2 ноября 2026 года № 3176-р: почти 700 млн руб. Пермскому краю и Курганской области (федеральный проект «Вода России»).", "http://government.ru/news/60397/"], ["МСП в Крыму", "Распоряжение № 3214-р: 350 млн руб. из резервного фонда Крыму и Севастополю на докапитализацию микрофинансовых организаций для поддержки МСП.", "http://government.ru/news/60391/"], ["Федеральное имущество", "Правкомиссия: в управление «ДОМ.РФ» передаются 11 земельных участков (15 га) и 17 зданий (почти 11 тыс. кв. м) в 11 регионах для поиска инвесторов.", "http://government.ru/news/60400/"], ["Топливо", "А. Новак и губернатор Красноярского края М. Котюков обсудили топливообеспечение региона.", "http://government.ru/news/60406/"]]}, "23.10.2026": {"nv": 1, "d": [["Председатель ГД", "Володин направил в комитеты по защите семьи и по труду внесенные законопроекты о поддержке семей с детьми. Больничный по уходу за ребенком увеличивается на 30 дней, до 150 дней в год (сейчас до 120). Изменения в ТК: пособие по уходу за ребенком до 1,5 лет сохраняется при выходе на работу, если в отпуске пробыли не менее 2 месяцев. Цель — применять с начала 2027 года. Номера законопроектов: подробности не раскрыты.", "http://duma.gov.ru/news/64312/"], ["Председатель ГД", "Володин участвовал в оперативном совещании Президента с членами Совбеза. Тема — молодежная политика, подробности не раскрыты.", "http://duma.gov.ru/news/64314/"]], "g": [["Распоряжение", "№ 3043-р от 23.10: более 2 млрд руб. Краснодарскому краю на очистные сооружения Геленджика, мощность 50 тыс. м³ в сутки. В 2018–2025 годах из федерального бюджета выделено около 10 млрд руб.", "http://government.ru/news/60268/"], ["Заседание", "Опубликованы решения заседания 22.10. Средства из резервного фонда — на коммунальную инфраструктуру Геленджика. Одобрены и вносятся в ГД законопроекты о поправках в КоАП (ответственность за вождение без прав) и в закон «О связи».", "http://government.ru/news/60272/"], ["Заявление", "Хуснуллин: в ЮФО с 2021 года по инфраструктурным кредитам привлечено 470,51 млрд руб. внебюджетных средств. Выполнены работы по 116 объектам из 165, введено 3,88 млн м² жилья, создано 14,6 тыс. рабочих мест.", "http://government.ru/news/60277/"], ["Совещание", "Мишустин участвовал в оперативном совещании Президента с членами Совбеза по видеосвязи. Подробности не раскрыты.", "http://government.ru/news/60279/"]]}, "25.10.2026": {"nv": 1, "d": [["Председатель ГД", "Нью-Дели, на полях XII Парламентского форума БРИКС: переговоры Володина со спикером Народной палаты Индии Омом Бирлой о межпарламентском сотрудничестве. Решения: подробности не раскрыты.", "http://duma.gov.ru/news/64321/"], ["Председатель ГД", "Переговоры Володина со спикерами парламентов Уганды, Кубы и Таиланда. Решения: подробности не раскрыты.", "http://duma.gov.ru/news/64322/"]], "g": [["—", "Содержательных решений на government.ru не опубликовано. Есть только поздравление Мишустина с 35-летием ФТС.", "http://government.ru/news/?dt.since=25.10.2026&dt.till=25.10.2026"]]}, "26.10.2026": {"nv": 1, "d": [["Комитет", "Комитет по бюджету и налогам рекомендовал принять проект федерального бюджета на 2027–2029 годы в первом чтении (двое воздержались). 2027: расходы 48,8 трлн руб., доходы 43,3 трлн; 2028: 50,9 и 45,8 трлн; 2029: 53,9 и 48,6 трлн. Пленарное рассмотрение — 29.10.", "http://duma.gov.ru/news/64340/"], ["Фракция", "Собрание фракции ЕР с А. Силуановым по проекту бюджета. Д. Кобылкин: фракция поддержит проект в первом чтении 29.10.", "http://duma.gov.ru/news/64333/"], ["Форум БРИКС", "Нью-Дели, XII Парламентский форум БРИКС (26–27.10). В. Володин предложил создать в парламентском измерении БРИКС экспертный совет по ИИ для обмена законодательными практиками.", "http://duma.gov.ru/news/64331/"], ["Форум БРИКС", "А. Сидякин предложил создать в БРИКС общий банк проверки ИИ-решений для социальной сферы; к 2030 году ИИ будут использовать 95% отраслей РФ.", "http://duma.gov.ru/news/64338/"], ["Председатель ГД", "Встречи В. Володина с премьером Индии Н. Моди, главой МИД Индии С. Джайшанкаром, делегацией ПК ВСНП КНР и председателем ФНС ОАЭ С. Гоббашем. Решения: подробности не раскрыты.", "http://duma.gov.ru/news/64326/"]], "g": [["Оперативное совещание", "Запорожской и Херсонской областям выделены средства на ~800 единиц оборудования пищеблоков в ~50 школах и детсадах (сумма не раскрыта). Мишустин поручил Силуанову довести финансирование до регионов. Олимпиада «Безопасные дороги» — более 6,5 млн участников.", "http://government.ru/news/60281/"], ["Совещание", "А. Новак, экономика: ВВП в августе +0,8% г/г, январь–август +0,6%; обработка +0,4%, машиностроение +6%; реальные зарплаты +6% за 7 мес.; безработица 2,2%. Ведомствам поручено проанализировать отклонения от прогноза.", "http://government.ru/news/60285/"], ["Нацпроект «Семья»", "Т. Голикова, итоги 9 месяцев: маткапитал — 1,6 млн семей (92% плана); семейная выплата — более 1,5 млн человек на 01.10; 450 тыс. руб. на ипотеку — свыше 92 тыс. многодетных семей в 2026 году.", "http://government.ru/news/60283/"], ["МАГАТЭ", "А. Новак открыл миссию МАГАТЭ ИРРС по оценке Ростехнадзора: 26 экспертов из 17 стран, 11 направлений, визиты на 5 объектов, до 6 ноября.", "http://government.ru/news/60284/"], ["Наука", "Д. Чернышенко: вузы «Приоритета-2030» (141 вуз) за 5 лет привлекли от индустрии почти 320 млрд руб.; передовых инженерных школ 50, будет 100.", "http://government.ru/news/60288/"], ["Прием в вузы", "Координационный совет при Правительстве одобрил КЦП на 2027/28: машиностроение +516 мест, информатика +290, клиническая медицина +283. Приказ — до 1 ноября.", "https://www.pnp.ru/social/v-vuzakh-uvelichat-chislo-byudzhetnykh-mest-po-vostrebovannym-specialnostyam.html"], ["Дороги", "М. Хуснуллин: начата вторая очередь развязки ЦКАД и Ленинградского шоссе — 5 съездов, ~2,5 км, завершение в 2027 году.", "http://government.ru/news/60287/"]]}, "30.10.2026": {"nv": 1, "d": [["Пленарного заседания не было", "На vote.duma.gov.ru за 30.10.2026 голосований не найдено. Пятница в пленарной неделе без открытых голосований.", "http://vote.duma.gov.ru/?from=30.10.2026&to=30.10.2026"], ["Комитет", "При Комитете по строительству и ЖКХ начал работу Экспертный совет (председатель — В. Ресин; первый зампред — С. Пахомов). Задачи: экспертиза законопроектов, нацпроект «Инфраструктура для жизни», обновление трети жилищного фонда за 5–6 лет (663 млн кв. м).", "http://duma.gov.ru/news/64382/"], ["Комитет", "Депутаты Комитета по развитию Дальнего Востока и Арктики на заседании комиссии Госсовета по СМП и Арктике рассмотрели проект закона «О единой территории опережающего развития Дальнего Востока и Арктики РФ».", "http://duma.gov.ru/news/64385/"], ["Комитет", "Б. Цыдыпов (Комитет по науке и высшему образованию) на круглом столе Ассоциации ведущих университетов — аспирантура и ИИ в науке; подробности законодательных решений не раскрыты.", "http://duma.gov.ru/news/64384/"], ["Комитет", "Депутаты Комитета по экономической политике — образовательная программа Сбербанка по ИИ (Аносино); М. Топилин: работа над законами об ЭПР, платформенной экономике, технологическом суверенитете, МТК.", "http://duma.gov.ru/news/64387/"], ["Комитет", "В. Кашин встретился с руководством профсоюза работников потребительской кооперации (О. Шелягов): восстановление потребкооперации, заготовка дикоросов, сельская торговля.", "http://duma.gov.ru/news/64383/"], ["БРИКС", "Пресс-конференция по итогам XII Парламентского форума БРИКС (Нью-Дели, 26–27.10): П. Толстой — многополярный мир; А. Бабаков — цели общего развития; М. Воропаева — обмен IT-практиками с Индией; В. Даванков — экспертный совет по ИИ; В. Гутенев — промышленность и ВТС; В. Кашин — 30% агроэкспорта в страны БРИКС; Н. Школкина — туризм (135 млн туристов в БРИКС за прошлый год), электронные визы с Индией.", "http://duma.gov.ru/news/64386/"]], "g": [["Распределение обязанностей", "М. Мишустин утвердил распределение обязанностей между вице-премьерами обновлённого кабинета: Д. Мантуров — нацпроекты «Средства производства и автоматизация», «Новые материалы и химия», «Промышленное обеспечение транспортной мобильности», космос до 2030/2036, биоэкономика; Т. Голикова — «Продолжительная и активная жизнь», «Семья», «Кадры», «Новые технологии сбережения здоровья»; О. Кожемяко — Дальний Восток и Арктика, Минвостокразвития; А. Никитин — транспорт, нацпроекты «Беспилотные авиационные системы» и «Эффективная транспортная система», Минтранс и Росавиация; А. Новак — дополнительно платформенная экономика и производительность труда, нацпроекты «Эффективная и конкурентная экономика», «Новые атомные и энергетические технологии».", "http://government.ru/news/60323/"], ["Росавиация", "М. Мишустин назначил Н. Андрианову врио руководителя Росавиации (ранее — заместитель руководителя с 2021 года).", "http://government.ru/news/60325/"], ["Кампусы", "Отобраны 19 новых проектов современных университетских кампусов в 17 городах (4-й отбор Минобрнауки): площадь около 2 млн кв. м, 29 тыс. мест проживания, финансирование 474 млрд руб. (224 млрд из федерального бюджета). В работе — 25 проектов в 23 регионах (896,93 млрд руб.); введено 41 объект из 123.", "http://government.ru/news/60316/"], ["Автобусы", "М. Хуснуллин: ещё 40 новых автобусов отечественного производства переданы восьми регионам (льготный лизинг Минпромторга и нацпроект «Инфраструктура для жизни»): Московская область — 22, Челябинская — 7, Липецкая — 3, Красноярский край — 3, Пермский край — 2 и др.", "http://government.ru/news/60321/"], ["РТК", "Т. Голикова провела заседание Российской трёхсторонней комиссии: поддержан проект поправок в ТК о профессионально-квалификационных характеристиках; рассмотрены итоги конкурса «Российская организация высокой социальной эффективности» (1424 организации, 53 победителя и призёра).", "http://government.ru/news/60320/"]]}, "31.10.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Суббота. На vote.duma.gov.ru за 31.10.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=31.10.2026&to=31.10.2026"], ["Председатель ГД", "В. Володин рассказал о законах, вступающих в силу в ноябре: с 3 ноября перечень статей КоАП, по которым иностранцев кроме штрафа выдворяют из страны, расширен с 22 до 45 (в т.ч. неповиновение полиции и пограничникам, оскорбительная информация в интернете, нарушение общественного порядка, дискредитация ВС РФ, призывы к санкциям, дискриминация).", "http://duma.gov.ru/news/64397/"], ["Законы ноября", "С 1 ноября на производителей вискового дистиллята распространены требования к производителям этилового спирта (уставный капитал от 100 млн руб.); упрощено расширение перечня госплатежей через специализированную систему; Казначейство передает сведения об уплате в ГИС ГМП не позднее чем через час. 2 ноября завершается эксперимент по автоматизации льготных авиаперевозок.", "http://duma.gov.ru/news/64396/"], ["Внесенные законопроекты", "Правительство внесло № 23992-9 (изменения в ст. 52 Градостроительного кодекса; направлен в Комитет по строительству и ЖКХ) и № 23969-9 (изменение в ст. 28.3 КоАП; направлен в Комитет по уголовному и административному законодательству). Полнота перечня sozd не проверена.", "https://sozd.duma.gov.ru/oz?b%5BClassOfTheObjectLawmakingId%5D=1&b%5BYear%5D=31.10.2026+-+02.11.2026&date_period_from_Year=31.10.2026&date_period_to_Year=02.11.2026&b%5Bsubmit%5D="], ["Совет Думы", "Заседаний Совета Думы 31.10 в открытых источниках не зафиксировано.", "http://duma.gov.ru/"]], "g": [["Экспорт топлива", "Постановление № 1436: запрет на экспорт дизельного и судового топлива, а также газойлей для непосредственных производителей продлен до 31.01.2027 включительно (ранее действовал по 31.10.2026). Общий запрет на экспорт топлива действует по 31.01.2027. Цель — стабильность внутреннего топливного рынка.", "http://government.ru/news/60326/"], ["Льготные кредиты", "Распоряжение № 3124-р от 30.10: из резервного фонда Правительства дополнительно выделено свыше 725 млн руб. на льготное кредитование аграриев — сохранение льготной ставки по 185 ранее выданным кредитам на производство и переработку сельхозпродукции.", "http://government.ru/docs/60324/"], ["Здравоохранение", "Т. Голикова поздравила НМИЦ оториноларингологии ФМБА с 90-летием: 550 операций кохлеарной имплантации в год, почти 17 тыс. пациентов в год; за 5 лет число пролеченных выросло более чем в 3,5 раза, объем ВМП — почти в 2 раза.", "http://government.ru/news/60337/"], ["Олимпиада", "Д. Чернышенко и С. Кравцов поздравили сборную России с победой на Международной молодежной олимпиаде по географии MY-GEO 2026 в «Сириусе» — первое место в командном и индивидуальном зачетах.", "http://government.ru/news/60340/"]]}, "01.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Воскресенье. На vote.duma.gov.ru за 01.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=01.11.2026&to=01.11.2026"], ["Председатель ГД", "В. Володин поздравил сотрудников и ветеранов ФССП с профессиональным праздником и Росфинмониторинг с 25-летием (противодействие коррупции и легализации преступных доходов).", "http://duma.gov.ru/news/64395/"], ["Председатель ГД", "В. Володин сообщил об открытии в деревне Дугино (Сычевский район Смоленской области) памятника «Защитникам России»; автор — саратовский скульптор В. Пальмин.", "http://duma.gov.ru/news/64398/"], ["Совет Думы", "Заседаний Совета Думы 01.11 в открытых источниках не зафиксировано.", "http://duma.gov.ru/"]], "g": [["ОПЕК+", "А. Новак как сопредседатель провел заседание группы семи стран ОПЕК+ (Саудовская Аравия, Россия, Ирак, Кувейт, Казахстан, Алжир, Оман): в декабре 2026 года сохраняется уровень добычи, установленный на сентябрь 2026 года. Следующая встреча — 29.11.2026.", "http://government.ru/news/60341/"], ["Запрет ввоза", "Опубликовано постановление № 1444 от 31.10 «О введении запрета на ввоз в Российскую Федерацию отдельных категорий товаров»; перечень товаров и сроки подробности не раскрыты.", "http://publication.pravo.gov.ru/document/0001202611010003"], ["Росаккредитация", "Д. Мантуров поздравил Росаккредитацию с 15-летием: системная работа позволила существенно сократить присутствие недобросовестных участников в сфере сертификации.", "http://government.ru/news/60339/"]]}, "02.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Региональная неделя (02–08.11). На vote.duma.gov.ru за 02.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=02.11.2026&to=02.11.2026"], ["Председатель ГД", "В. Володин: с 3 ноября перечень статей КоАП с выдворением иностранцев кроме штрафа расширен с 22 до 45; в сфере миграции с 2024 года принято 32 федеральных закона, из них 21 инициирован депутатами.", "http://duma.gov.ru/news/64400/"], ["Бюджет", "По поручению В. Володина председатель Комитета по бюджету и налогам А. Макаров встретился с президентом ТПП С. Катыриным: подготовка ко второму чтению бюджета на 2027–2029 годы, поправки в Бюджетный и Налоговый кодексы; предложения ТПП отражены в заключении и в постановлении ГД о первом чтении.", "http://duma.gov.ru/news/64403/"], ["Конкурс СМИ", "Объявлен ежегодный конкурс журналистов на лучшее освещение деятельности Госдумы в 2026 году: 7 номинаций, материалы принимаются до 01.12.2026, итоги — ко Дню российской печати (13 января).", "http://duma.gov.ru/news/64399/"], ["Внесенные законопроекты", "№ 24858-9 (С. Миронов и др.) — запрет премирования руководства при задолженности по зарплате (Трудовой кодекс); № 24118-9 (Сахалинская областная Дума) — изменения в закон об эксперименте с гостевыми домами. Полнота перечня sozd не проверена.", "https://sozd.duma.gov.ru/oz?b%5BClassOfTheObjectLawmakingId%5D=1&b%5BYear%5D=31.10.2026+-+02.11.2026&date_period_from_Year=31.10.2026&date_period_to_Year=02.11.2026&b%5Bsubmit%5D="], ["Совет Думы", "Заседаний Совета Думы 02.11 в открытых источниках не зафиксировано.", "http://duma.gov.ru/"]], "g": [["Оперативное совещание", "М. Мишустин провел совещание с вице-премьерами: план реализации Энергетической стратегии до 2050 года, внедрение научно-технологических достижений в АПК (доля семян отечественной селекции почти 70% при цели не менее 75%), поддержка рыбохозяйственного комплекса.", "http://government.ru/news/60332/"], ["Энергостратегия", "Распоряжение № 3170-р от 31.10: план первого этапа Энергетической стратегии до 2050 года — более 80 мероприятий на 2027–2029 годы: надежность энергоснабжения, модернизация, производство комплектующих, умная энергетика, рост доли ВИЭ, международное сотрудничество, кадры.", "http://government.ru/news/60329/"], ["Нефтехимия", "Постановление № 1443 от 31.10: на 3 месяца запрещен вывоз за пределы ЕАЭС каменноугольного и нефтяного бензолов, толуола, ортоксилола, параксилола, фенола. Исключения — транзит, гуманитарная помощь, Шпицберген.", "http://government.ru/news/60327/"], ["Семена", "Постановление № 1434 от 30.10: с 01.01.2027 в госпрограмме АПК — субсидии на приобретение и высев семян отечественной селекции; возмещение затрат по комплексным научно-техническим проектам (свыше 50). В проекте бюджета на 2027 год — около 4 млрд руб.", "http://government.ru/news/60338/"], ["Финансовая устойчивость", "А. Новак провел подкомиссию по устойчивости финансового сектора (М. Орешкин, А. Жуков, М. Решетников): в план структурных изменений до 2030 года добавляются 3 индикатора — дефицит региональных бюджетов, число регионов с высокой безработицей и с низкой инвестактивностью; предложения в целом одобрены.", "http://government.ru/news/60345/"], ["Здравоохранение", "Т. Голикова на V конгрессе «Национальное здравоохранение»: финансирование базовой программы ОМС за около 20 лет выросло почти в 23 раза — с 219 млрд до 5 трлн руб.; утверждена Стратегия развития здравоохранения до 2030 года.", "http://government.ru/news/60351/"]]}, "03.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Региональная неделя (02–08.11). На vote.duma.gov.ru за 03.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=03.11.2026&to=03.11.2026"], ["Бюджет", "По поручению В. Володина А. Макаров (Комитет по бюджету и налогам) встретился с главой РСПП А. Шохиным и председателем «Деловой России» А. Репиком: доработка ко второму чтению бюджета на 2027–2029 годы и поправок в Бюджетный и Налоговый кодексы. Обе организации поддержали бюджет в первом чтении; часть их замечаний отражена в заключении комитета, работа над налоговыми законопроектами продолжится.", "http://duma.gov.ru/news/64406/"], ["Председатель ГД", "В. Володин в Саратове: до конца года создадут 3175 ученических мест — три школы (1100, 825 и 550 мест) и две пристройки по 350 мест; цель — переход на односменное обучение.", "http://duma.gov.ru/news/64405/"], ["Комитеты", "Комитет по защите семьи провел рабочие группы «Семья и школа: сохранение традиционных духовных ценностей» и «Об основах регулирования психологической деятельности в Российской Федерации».", "http://duma.gov.ru/news/64404/"], ["Внесенные законопроекты", "Президент внес № 25979-9 и № 25978-9 о ратификации договоров с Зимбабве и Камбоджей о передаче осужденных к лишению свободы. Депутаты «Новых людей» (В. Даванков и др.) внесли № 25877-9 — изменения в ст. 219 НК РФ (социальные вычеты по НДФЛ, подробности не раскрыты). Также внесены № 25914-9 (С. Миронов и др., ст. 28 закона «О ветеранах»), № 25268-9 (Л. Слуцкий и др., ст. 53 закона о службе в ОВД), № 25960-9 (Законодательное Собрание Псковской области, эксперимент с гостевыми домами). Всего на sozd за 03.11 — 6 законопроектов.", "https://sozd.duma.gov.ru/oz?b%5BClassOfTheObjectLawmakingId%5D=1&b%5BYear%5D=03.11.2026+-+03.11.2026&date_period_from_Year=03.11.2026&date_period_to_Year=03.11.2026&b%5Bsubmit%5D="], ["Совет Думы", "Заседаний Совета Думы 03.11 в открытых источниках не зафиксировано.", "http://duma.gov.ru/"]], "g": [["Заседание Правительства", "М. Мишустин провел заседание № 37. В повестке: функции Минцифры по координации внедрения ИИ, субсидия ДОМ.РФ на возмещение доходов по IT-ипотеке, восстановление дорог в Дагестане и Чечне после паводков 2026 года, поправки Правительства к законопроекту № 1209623-8 об аккредитации и аттестации медиков, отмена отдельных пунктов положения о Минтруде, субсидии регионам на озимые.", "http://government.ru/news/60357/"], ["Радиоэлектроника", "Расширен перечень продукции для налогового режима производителей радиоэлектроники (пониженная ставка налога на прибыль и страховых взносов): оборудование для печатных пластин, полупроводниковые слитки и пластины, интегральные схемы, дисплеи; льготы по взносам — для производителей ряда лазерных систем.", "http://government.ru/news/60357/"], ["Рыбный порт", "Распоряжение № 3166-р от 31.10: около 600 млн руб. на завершение строительства рыбного порта в морском порту Корсаков (Сахалинская область); порт войдет в Трансарктический транспортный коридор.", "http://government.ru/docs/60356/"], ["Урожай 2027", "Более 13 млрд руб. на агротехнологические работы под озимые для 22 регионов (более 5,5 млн га) — поддержка аграриев, пострадавших от сбоев логистики в Азово-Черноморском бассейне.", "http://government.ru/news/60357/"], ["Дальний Восток", "О. Кожемяко провел встречи с губернатором Магаданской области С. Носовым (мастер-план до 2030 года, 100-летие Магадана в 2029 году) и главой Якутии А. Николаевым (северный завоз, ЖКХ, авиация, дноуглубление, коридор Мохэ — Найба).", "http://government.ru/news/60358/"]]}, "04.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "04.11.2026 — День народного единства (нерабочий праздничный день). Региональная неделя (02–08.11). На vote.duma.gov.ru за 04.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=04.11.2026&to=04.11.2026"], ["Председатель ГД", "В. Володин поздравил россиян с Днем народного единства: сплоченность, любовь к Родине и бережное отношение к общей истории и культуре объединяют общество и помогают противостоять вызовам.", "http://duma.gov.ru/news/64409/"], ["Внесенные законопроекты", "На sozd.duma.gov.ru за 04.11.2026 внесенных законопроектов в открытой выдаче не найдено (государственный праздник — День народного единства).", "https://sozd.duma.gov.ru/"], ["Совет Думы", "Заседаний Совета Думы 04.11 в открытых источниках не зафиксировано.", "http://duma.gov.ru/"]], "g": [["Поздравление", "М. Мишустин поздравил с Днем народного единства: праздник — символ сплоченности и гражданского подвига многонационального народа, отстоявшего независимость Отечества в 1612 году; солидарность и любовь к Родине — основа суверенитета, развития и процветания России.", "http://government.ru/news/60364/"], ["Решения заседания 02.11", "Опубликованы решения заседания Правительства от 02.11.2026 (6 вопросов): координация внедрения ИИ — функции Минцифры; субсидия ДОМ.РФ на возмещение доходов по IT-ипотеке; трансферты Дагестану и Чечне на дороги после паводков; поправки к законопроекту № 1209623-8 об аккредитации и аттестации медиков; отмена отдельных положений о Минтруде; субсидии регионам на озимые.", "http://government.ru/news/60366/"]]}, "05.11.2026": {"nv": 1, "d": [["Пленарного заседания не было", "Региональная неделя (02–08.11). На vote.duma.gov.ru за 05.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=05.11.2026&to=05.11.2026"], ["Председатель ГД", "В. Володин поздравил сотрудников и ветеранов Главного управления Генштаба Вооруженных Сил с профессиональным праздником (День военного разведчика): разведчики вносят вклад в защиту суверенитета и безопасность граждан, решают оперативные и стратегические задачи.", "http://duma.gov.ru/news/64410/"], ["Внесенные законопроекты", "На sozd за 05.11 — 6 законопроектов. С. Миронов, С. Кабышев, Н. Стариков, В. Гартунг, В. Швецов, А. Аксененко — № 27227-9: специальный инвестиционный вычет по налогу на прибыль — 50% расходов на создание и модернизацию систем защиты объектов от воздушного нападения, в том числе беспилотников (не более 100 млн руб. на налогоплательщика). Ю. Афонин, Н. Останина, А. Куринный, М. Дробот, Г. Камнев и сенатор А. Гибатдинов — № 26560-9: 100% штрафов за несоблюдение требований к содержанию животных зачислять в бюджеты регионов (содержание собаки в приюте — до 240 тыс. руб. в год), и № 26541-9 (изменения в КоАП, подробности не раскрыты). Брянская областная Дума — № 26969-9: суммирование снижения пенсионного возраста за проживание (работу) в разных чернобыльских зонах (сейчас — только через суд; в Брянской области в 2023–2025 годах удовлетворено 405, 489 и 402 иска); № 27235-9: терминология ст. 8.21 КоАП (охрана атмосферного воздуха) по закону № 96-ФЗ; № 27273-9: в ст. 346.38 НК РФ «бонусы» по соглашениям о разделе продукции переименовать в «разовый платеж за пользование недрами».", "https://sozd.duma.gov.ru/oz?b%5BClassOfTheObjectLawmakingId%5D=1&b%5BYear%5D=05.11.2026+-+05.11.2026&date_period_from_Year=05.11.2026&date_period_to_Year=05.11.2026&b%5Bsubmit%5D="], ["Совет Думы", "Заседаний Совета Думы 05.11 в открытых источниках не зафиксировано.", "http://duma.gov.ru/"]], "g": [["Совещание у Президента", "М. Мишустин и члены Правительства участвовали в совещании В. Путина с членами Правительства (видеоконференция). Первый вопрос — развитие СПО: по данным С. Кравцова, в колледжах учатся 4 млн студентов, прием вырос с 900 тыс. до 1,4 млн человек, в колледжи «Профессионалитета» поступили 700 тыс. первокурсников; на капремонт колледжей до 2030 года предусмотрено более 110 млрд руб. (почти 20 млрд — в 2026 году), в 2026 году ремонтируют 259 колледжей. Запущен федеральный технопарк подготовки мастеров производственного обучения в Нижнем Новгороде.", "http://kremlin.ru/events/president/news/81185"], ["Отопительный сезон", "М. Хуснуллин провел президиум Правкомиссии по региональному развитию: тепло подается почти в 3 тыс. муниципалитетов 87 регионов (в 81 — во всех), готовность коммунальной инфраструктуры — 99%, запасено 5,4 млн т угля и 2,4 млн т жидкого топлива. Программа модернизации ЖКХ на средства ФНБ — 150 млрд руб.: одобрено 258 проектов в 76 регионах, работы завершены на 1326 объектах (310 площадных и 1,53 тыс. км сетей).", "http://government.ru/news/60370/"], ["Трасса М-4", "Главгосэкспертиза одобрила первые 3 из 6 этапов реконструкции М-4 «Дон» Джубга — Геленджик (1441–1503 км): всего около 60 км, из них 24 км — расширение до 4 полос и 33,9 км — новые двухполосные обходы; первые этапы — около 15 км и обход села Бжид (2,8 км, эстакада 212 м).", "http://government.ru/news/60372/"], ["Нацпроект здоровья", "Т. Голикова провела проектный комитет нацпроекта «Новые технологии сбережения здоровья»: в 2025–2026 годах идет 31 исследование (ожидаются 5 препаратов, 21 медизделие, 5 технологий); онковакцину CaTeVac планируют применять с 2027 года при саркомах мягких тканей; зарегистрировано 40 препаратов из перечня ЖНВЛП, ранее не производившихся в России (15 — в 2026 году), и более 1,8 тыс. медизделий.", "http://government.ru/news/60368/"], ["Кампусы", "Д. Чернышенко: к 2036 году — не менее 40 кампусов, отобраны 19 новых участников. В калининградском кампусе введено 6 из 8 объектов, готовность 94%, открытие — в конце апреля 2027 года к 80-летию БФУ им. И. Канта. До 2030 года — не менее 12 передовых школ в 12 регионах (строятся в Нижегородской, Псковской и Рязанской областях; в Бору — на 800 мест).", "http://government.ru/news/60369/"], ["Устойчивость АПК", "Д. Мантуров, А. Новак и Д. Патрушев провели заседание подкомиссии по бесперебойному функционированию отраслей экономики — работа АПК: безопасность работников и физическая защита критических объектов, стабильные поставки семян, удобрений, кормов, ветпрепаратов и топлива, резервные источники энергоснабжения. Цифры не раскрыты.", "http://government.ru/news/60373/"], ["IT-ипотека", "Распоряжение № 3189-р от 03.11 (опубл. 05.11): Минцифры из резервного фонда 7,7 млрд руб. на субсидию ДОМ.РФ для возмещения банкам недополученных доходов по IT-ипотеке; результат — улучшение жилищных условий не менее 102,5 тыс. IT-специалистов до конца 2026 года.", "http://publication.pravo.gov.ru/document/0001202611050052"], ["Помощь Дагестану", "Распоряжение № 3204-р: МЧС из резервного фонда 206,7 млн руб. на трансферт Дагестану — возмещение единовременной материальной помощи гражданам, пострадавшим от ЧС из-за непогоды в марте — апреле 2026 года.", "http://publication.pravo.gov.ru/document/0001202611050048"], ["Дивиденды госдолей", "Распоряжение № 3201-р: ООО с федеральными долями должны направлять участникам не менее 50% прибыли за год по консолидированной отчетности МСФО (без учета обесценения активов, переоценки финансовых активов и курсовых разниц), если иное не установлено актами Правительства.", "http://publication.pravo.gov.ru/document/0001202611050053"]]}, "13.11.2026": {"nv": 1, "d": [["Голосований не было", "На vote.duma.gov.ru за 13.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=13.11.2026&to=13.11.2026"]]}, "16.11.2026": {"nv": 1, "d": [["Голосований не было", "На vote.duma.gov.ru за 16.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=16.11.2026&to=16.11.2026"]]}, "20.11.2026": {"nv": 1, "d": [["Голосований не было", "На vote.duma.gov.ru за 20.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=20.11.2026&to=20.11.2026"]]}, "23.11.2026": {"nv": 1, "d": [["Голосований не было", "На vote.duma.gov.ru за 23.11.2026 голосований не найдено.", "http://vote.duma.gov.ru/?from=23.11.2026&to=23.11.2026"]]}};
