    const totB = <div data-sec="vote" style={{ ...box, display: 'flex', flexDirection: 'column', gap: 6 }}><div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}><div style={{ ...hG, marginBottom: 0 }}>Итоги голосования</div>{vtG}</div><div style={{ display: 'flex', alignItems: 'center', gap: 16 }}><div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: 3 }}>{CATn.map((n, i) => <div key={n} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 14 }}><span style={{ width: 9, height: 9, borderRadius: 9, background: SYS[i], flexShrink: 0 }} /><span style={{ flex: 1, color: i === 3 ? t.text.secondary : t.text.primary }}>{n}</span><b style={{ fontVariantNumeric: 'tabular-nums', color: SYS[i] }}>{v.total[i]}</b></div>)}</div><div style={{ width: m ? 76 : 96, flexShrink: 0 }}><Donut v={v.total} size={m ? 76 : 96} center={String(tot)} sub={rjm ? 'за откл.' : 'за'} nw={nw} /></div></div></div>;
