    const lkS = { display: 'inline-flex', alignItems: 'center', gap: 4, height: 28, padding: '0 11px', borderRadius: 14, border: 'none', background: DK ? '#2F3642' : '#DFE6F0', fontFamily: t.font.family, fontSize: 13, color: t.text.accent, textDecoration: 'none', whiteSpace: 'nowrap', cursor: 'pointer' } as any;
    const passN = pass.filter(([, x]) => x).map(([k, x]) => { const mm = typeof k === 'string' && x === '\u00a0' ? k.match(/^(Инициаторы?)\s+—\s+(.+)$/) : null; return mm ? [mm[1], mm[2].charAt(0).toUpperCase() + mm[2].slice(1)] : [k, x]; }) as [string, any][];
