          {m ? <><span style={{ flex: 1, minWidth: 0 }}>{title} <span style={{ color: t.text.tertiary, fontWeight: t.weight.regular }}>{items.length}</span></span><span aria-hidden style={{ color: t.text.tertiary, transition: 'transform .2s', transform: o ? 'rotate(90deg)' : 'none' }}>›</span></> : <>{o ? '▾' : '▸'} {title} ({items.length})</>}
