  if (S.nv && (S.d || []).length) D.push(['Главное за день', (S.d as string[][]).map((g) => [`${g[0]}: ${g[1]}`, g[2]] as [string, string])]);
  if (!S.nv) ['3-е', '2-е', '1-е'].filter((r) => laws[r]).forEach((r) => D.push([`Законопроекты, принятые ${r === '2-е' ? 'во' : 'в'} ${word[r]} чтении`, laws[r].map((v) => [`${v.doc}: ${v.q} (${v.total[0]} за)`, `http://vote.duma.gov.ru/vote/${v.id}`] as [string, string])]));
  if (!S.nv && dec.length) D.push(['Постановления и организационные решения', dec.map((v) => [`${v.doc !== '—' ? v.doc + ': ' : ''}${v.q}`, `http://vote.duma.gov.ru/vote/${v.id}`] as [string, string])]);
