  const wkOk = (d: Date) => wOff.some((o) => d >= wStart(o) && d <= wEnd(o)); const mon = wStart(wOff[0]); const sun = wEnd(wOff[wOff.length - 1]); /* 21.11.2026: недель можно выбрать несколько, итоги суммируются */
