const newsOrg = (o: string, day: string): any[] => (o === 'sf' ? SFN[day] || [] : ORGNEWS.filter((x: any) => x.o === o && x.d === day));
const ORGN: Record<string, string> = { sf: 'Совет Федерации', pres: 'Президент', minfin: 'Минфин', mintrud: 'Минтруд', minjust: 'Минюст', cbr: 'Банк России', gov: 'Правительство', economy: 'Минэкономразвития', promtorg: 'Минпромторг', minzdrav: 'Минздрав', mintrans: 'Минтранс', digital: 'Минцифры', mvd: 'МВД', mnr: 'Минприроды', minstroy: 'Минстрой' };
 
 ORGG.forEach(([g, , os]) => os.forEach((o) => { ORGGO[o] = g; }));
