function calCks(): string[] { const n = new Date(); const st = new Set<string>([0, 1].map((k) => calCk(new Date(n.getFullYear(), n.getMonth() + k, 1)))); [...CAL.p.map((x: any) => x.d), ...CAL.g.map((x: any) => x[0]), ...ORG.map((x: any) => x.d), ...CAL.w.flatMap((x: any) => [x[0], x[1]]), ...(GDX ? GDX.M.months.map((k: string) => '01.' + k) : [])].forEach((d: string) => { if (d) st.add(calCk(pd(d))); }); return [...st].sort((a, b) => (a.slice(3) + a.slice(0, 2)).localeCompare(b.slice(3) + b.slice(0, 2))); }
const calCnt = (k: string) => GDX && GDX.M.cnt[k] && !GDX.has(k) ? (() => { const c = GDX.M.cnt[k]; return (cof('gd') ? c.p : 0) + (cof('gov') ? c.g : 0) + new Set(Object.keys(c.o).filter(cof).flatMap((o) => c.o[o])).size; })() : (cof('gd') ? CAL.p.filter((x: any) => calCk(pd(x.d)) === k).length : 0) + (cof('gov') ? CAL.g.filter((x: any) => calCk(pd(x[0])) === k).length : 0) + new Set(ORG.filter((x: any) => (orgPub(x) || orgNoText(x)) && cof(x.o) && calCk(pd(x.d)) === k).map((x: any) => x.d)).size;
let SHB: Record<string, string> | null = null;
function agShort(bn: string, raw: string, day?: string): string { if (!billNo(bn)) return raw; /* 19.11.2026: в карточке дня — короткое название голосования этого же дня; если тексты дня еще не написаны, полное название из СОЗД, а не SHORT другого дня (так на 18.11 показывалось название из октября) */ if (day && DATA[day]) { const ls = DATA[day].split('\n').map((l) => l.split('|')).filter((z) => z[1] === bn); if (ls.length) { const o = ls.find((z) => SHORT[z[0]] && !/таб\./.test(z[3] || '')) || ls.find((z) => SHORT[z[0]]); if (o) return SHORT[o[0]]; const b = billNo(bn)!; return fullT(b, (INFO[b] || {}).t) || raw; } } /* 14.11.2026: у пункта без номера законопроекта нет своего короткого названия (раньше подставлялось «Порядок работы» от процедурного голосования) */ if (!SHB) { SHB = {}; for (const d of Object.keys(DATA)) for (const l of DATA[d].split('\n')) { const p = l.split('|'); if (p[1] && SHORT[p[0]] && !SHB[p[1]] && !/таб\./.test(p[3] || '')) SHB[p[1]] = SHORT[p[0]]; /* 17.11.2026: название законопроекта не берется от голосования по таблице поправок */ } } return SHB[bn] || AGSH[bn] || raw; }
/* 19.11.2026: полное официальное название пункта целиком — без многоточия vote.duma.gov.ru, если в INFO (СОЗД) или повестке есть полное */
const agFull = (x: any): string => { const f = (x && x[4]) || ''; const b = x ? billNo(x[0]) : null; return b ? fullT(b, f, (INFO[b] || {}).t) || f : f; };
 
function dayBillLines(bn: string, d: string): string[][] { return (DATA[d] || '').split('\n').map((x) => x.split('|')).filter((z) => z[1] === bn); }
