        {/* 15.11.2026: кнопка «Подписаться на мою ленту» (OPML) убрана по решению владельца; RSS по меткам — на странице «Подписки» (feed/). */}
        <div style={{ padding: 12, flexShrink: 0, borderTop: `1px solid ${t.border.subtle}` }}><button data-zapply="1" onClick={() => { if (omm) { setOMS({ feed: !oAll && !oNone }); setOp(null); return; } if (n && !laws) zClrQ(); setOp(null); }} style={{ width: '100%', minHeight: 46, border: 'none', borderRadius: 12, background: t.text.accent, color: '#fff', fontFamily: t.font.family, fontSize: 16, fontWeight: 600, cursor: 'pointer' }}>{omm ? (oNone ? 'Орган не выбран' : oAll ? 'Показать карту' : omW ? 'Показать' : `Показать ${OMPL(omIn.filter((x: any) => cof(x.o)).length, ['карточку', 'карточки', 'карточек'])}`) : n ? (ld ? (() => { const q = R!.filter((r) => zOkG(r.g)).length; const a = q % 10, b = q % 100; return `Показать ${q} ${laws ? (a === 1 && b !== 11 ? 'закон' : a >= 2 && a <= 4 && (b < 12 || b > 14) ? 'закона' : 'законов') : a === 1 && b !== 11 ? 'карточку' : a >= 2 && a <= 4 && (b < 12 || b > 14) ? 'карточки' : 'карточек'}`; })() : 'Показать') : 'Показать все'}</button></div>
