const myOk = (g: any) => { if (!g) return false; const w = myW(), t = myT(); if (!w.length && !t.length) return false; return (!w.length || w.some((v) => (g[0] || []).includes(v))) && (!t.length || t.some((v) => (g[1] || []).includes(v))); };
let mySyncTm: any = 0;
function mySync() { clearTimeout(mySyncTm); mySyncTm = setTimeout(async () => { try { if (!TG || !TG.initData || !STATS_URL) return; const any = MY.tags.length > 0 && (MY.n.vote || MY.n.new || MY.n.soon);
  const r = await fetch(`${STATS_URL}/sub`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ initData: TG.initData, w: any ? myW() : [], t: any ? myT() : [], prefs: { ...MY.n, tz: -new Date().getTimezoneOffset() } }) }); MYST = r.ok ? 'ok' : 'err'; } catch (e) { MYST = 'err'; } MYL.forEach((f) => f()); }, 800); }
